 $s->disqualify($event,$third,'Edited after submission');$s->transition($event,'published');
 $ranked=$s->entries($event);$check((int)$ranked[0]['result_rank']===1&&(int)$ranked[1]['result_rank']===1,'shared ties');$check((float)$ranked[0]['result_score']===27.0,'averaged score');$check(count($s->reviews($event))===4,'score edits must replace reviews');
 $reject(fn()=>$s->score($event,$first,3,0,0,0,''),'frozen scores');$reject(fn()=>$s->transition($event,'open'),'no reopen');$reject(fn()=>$s->disqualify($event,$first,'Late'),'frozen disqualifications');
