 $payload=['csrf'=>$_SESSION['creator_csrf'],'operation'=>'submit','event'=>(string)$open,'level'=>'10','username'=>'Creator1','password'=>'Creator-fixture-1'];
 $reply=$controller->handle(new Request('POST','/extensions/creator-events',[],$payload,['HTTPS'=>'on','REMOTE_ADDR'=>'127.0.0.1']));$check($reply->status===200&&count($s->entries($open))===1,'authenticated portal submission');
 $payload['csrf']=$_SESSION['creator_csrf'];$payload['password']='wrong';$check($controller->handle(new Request('POST','/extensions/creator-events',[],$payload,['HTTPS'=>'on','REMOTE_ADDR'=>'127.0.0.1']))->status===400,'invalid portal password');
 $router=new Router();$manager=new PluginManager($db,$router,sys_get_temp_dir().'/creator-missing-directory','1.1.0');$manager->load();$check(isset($manager->loaded()['creator-events']),'bundled SDK plugin loads without custom folder');
 $check($router->dispatch(new Request('GET','/extensions/creator-events',[],[],['HTTPS'=>'on']))->status===200,'SDK route dispatch');
 $_GET['creator_event']=(string)$event;ob_start();CreatorEventsAdmin::render($db);$html=ob_get_clean();$check(str_contains($html,'Jury scorecards')&&str_contains($html,'Disable')&&!str_contains($html,'<script>Rules'),'admin workspace');
